    #[test]
    fn test_application_layer_application_is_defined() {
        let input = EvaluateInput::new(
            serde_json::json!({"code": "x"}),
            Rubric::inline(serde_json::json!({"quality": 0.9})),
            Uuid::new_v4(),
            Uuid::new_v4(),
            "n",
        );
        assert_eq!(input.context.node_name, "n");
    }

    #[test]
    fn test_application_layer_application_interacts_with_none() {
        let input = EvaluateInput::new(
            serde_json::json!({"code": "x"}),
            Rubric::inline(serde_json::json!({"quality": 0.9})),
            Uuid::new_v4(),
            Uuid::new_v4(),
            "n",
        );
        let json = serde_json::to_string(&input).unwrap();
        assert!(serde_json::from_str::<EvaluateInput>(&json).is_ok());
    }
